 18	static bool span_is(base_bytes source, svg_xml_span span, const char *literal)
 19	{
 20	    size_t length = 0U;
 21	    while (literal[length] != '\0') length++;
 22	    return span.offset <= source.len && span.length == length &&
 23	           length <= source.len - span.offset &&
 24	           memcmp(source.ptr + span.offset, literal, length) == 0;
 25	}
 26	
 27	static bool attribute(base_bytes source, const svg_xml_token *tokens,
 28	                      size_t count, size_t element, const char *local,
 29	                      const char *prefix, svg_xml_span *out)
 30	{
 31	    for (size_t i = element + 1U;
 32	         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
 33	        if (!span_is(source, tokens[i].local_name, local)) continue;
 34	        if (prefix == NULL ? tokens[i].prefix.length == 0U :
 35	            span_is(source, tokens[i].prefix, prefix)) {
 36	            *out = tokens[i].value;
 37	            return true;
 38	        }
 39	    }
 40	    return false;
 41	}
 42	
 43	static int base64_value(uint8_t byte)
 44	{
 45	    if (byte >= 'A' && byte <= 'Z') return (int)(byte - 'A');
 46	    if (byte >= 'a' && byte <= 'z') return (int)(byte - 'a') + 26;
 47	    if (byte >= '0' && byte <= '9') return (int)(byte - '0') + 52;
 48	    if (byte == '+') return 62;
 49	    if (byte == '/') return 63;
 50	    return -1;
 51	}
 52	
 53	static bool decode_base64(svg_shape_builder *builder, base_bytes source,
 54	                          svg_xml_span payload, uint8_t **out,
 55	                          size_t *out_length)
 56	{
 57	    *out = NULL;
 58	    *out_length = 0U;
 59	    if (payload.length == 0U || payload.length > SVG_IMAGE_MAX_URI_BYTES ||
 60	        payload.length % 4U != 0U || payload.offset > source.len ||
 61	        payload.length > source.len - payload.offset) {
 62	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT, payload.offset);
 63	        return false;
 64	    }
 65	    size_t padding = 0U;
 66	    if (source.ptr[payload.offset + payload.length - 1U] == '=') padding++;
 67	    if (payload.length > 1U &&
 68	        source.ptr[payload.offset + payload.length - 2U] == '=') padding++;
 69	    size_t groups = payload.length / 4U;
 70	    if (groups > SIZE_MAX / 3U) {
 71	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT, payload.offset);
 72	        return false;
 73	    }
 74	    size_t decoded_length = groups * 3U - padding;
 75	    if (decoded_length == 0U || decoded_length > SVG_IMAGE_MAX_ENCODED_BYTES) {
 76	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT, payload.offset);
 77	        return false;
 78	    }
 79	    uint8_t *decoded = svg_shape_malloc(decoded_length);
 80	    if (decoded == NULL) {
 81	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_OOM, payload.offset);
 82	        return false;
 83	    }
 84	    size_t output = 0U;
 85	    for (size_t group = 0U; group < groups; ++group) {
 86	        size_t at = payload.offset + group * 4U;
 87	        int a = base64_value(source.ptr[at]);
 88	        int b = base64_value(source.ptr[at + 1U]);
 89	        bool final = group + 1U == groups;
 90	        int c = source.ptr[at + 2U] == '=' ? 0 :
 91	                base64_value(source.ptr[at + 2U]);
 92	        int d = source.ptr[at + 3U] == '=' ? 0 :
 93	                base64_value(source.ptr[at + 3U]);
 94	        bool legal_padding = final &&
 95	            ((source.ptr[at + 2U] == '=' && source.ptr[at + 3U] == '=') ||
 96	             (source.ptr[at + 2U] != '=' && source.ptr[at + 3U] == '='));
 97	        if (a < 0 || b < 0 || c < 0 || d < 0 ||
 98	            ((source.ptr[at + 2U] == '=' || source.ptr[at + 3U] == '=') &&
 99	             !legal_padding) ||
100	            (source.ptr[at + 2U] == '=' && (b & 15) != 0) ||
101	            (source.ptr[at + 3U] == '=' && source.ptr[at + 2U] != '=' &&
102	             (c & 3) != 0)) {
103	            svg_shape_free(decoded);
104	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
105	                           at);
106	            return false;
107	        }
108	        uint32_t bits = ((uint32_t)a << 18U) | ((uint32_t)b << 12U) |
109	                        ((uint32_t)c << 6U) | (uint32_t)d;
110	        decoded[output++] = (uint8_t)(bits >> 16U);
111	        if (source.ptr[at + 2U] != '=')
112	            decoded[output++] = (uint8_t)(bits >> 8U);
113	        if (source.ptr[at + 3U] != '=')
114	            decoded[output++] = (uint8_t)bits;
115	    }
116	    if (output != decoded_length) {
117	        svg_shape_free(decoded);
118	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
119	                       payload.offset);
120	        return false;
121	    }
122	    *out = decoded;
123	    *out_length = decoded_length;
124	    return true;
125	}
