127	static bool data_payload(base_bytes source, svg_xml_span uri,
128	                         svg_xml_span *payload)
129	{
130	    if (uri.offset > source.len || uri.length > source.len - uri.offset)
131	        return false;
132	    size_t comma = uri.offset;
133	    size_t end = uri.offset + uri.length;
134	    while (comma < end && source.ptr[comma] != ',') comma++;
135	    if (comma == end || comma + 1U == end) return false;
136	    size_t header_length = comma - uri.offset;
137	    static const char png[] = "data:image/png;base64";
138	    static const char jpeg[] = "data:image/jpeg;base64";
139	    if (!((header_length == sizeof(png) - 1U &&
140	           memcmp(source.ptr + uri.offset, png, sizeof(png) - 1U) == 0) ||
141	          (header_length == sizeof(jpeg) - 1U &&
142	           memcmp(source.ptr + uri.offset, jpeg, sizeof(jpeg) - 1U) == 0)))
143	        return false;
144	    *payload = (svg_xml_span){comma + 1U, end - comma - 1U};
145	    return true;
146	}
