148	static bool image_geometry(svg_shape_builder *builder, void *opaque)
149	{
150	    image_geometry_context *context = opaque;
151	    base_bytes source = context->source;
152	    svg_xml_token *tokens = context->tokens;
153	    size_t element = context->element;
154	    const char *names[] = {"x", "y", "width", "height"};
155	    double values[4] = {0.0, 0.0, 0.0, 0.0};
156	    bool has_width = false, has_height = false;
157	    for (size_t i = 0U; i < 4U; ++i) {
158	        svg_xml_span span;
159	        if (!attribute(source, tokens, context->token_count, element,
160	                       names[i], NULL, &span)) continue;
161	        if (i == 2U) has_width = true;
162	        if (i == 3U) has_height = true;
163	        double reference = i == 0U || i == 2U ?
164	            builder->viewport_width : builder->viewport_height;
165	        if (!svg_shape_read_length(source, span, reference, &values[i])) {
166	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_NUMBER, span.offset);
167	            return false;
168	        }
169	    }
170	    if (!has_width || !has_height || values[2] < 0.0 || values[3] < 0.0) {
171	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_NUMBER,
172	                       tokens[element].name.offset);
173	        return false;
174	    }
175	    svg_shape_image image = {
176	        .x = values[0], .y = values[1],
177	        .width = values[2], .height = values[3],
178	        .draw_x = values[0], .draw_y = values[1],
179	        .draw_width = values[2], .draw_height = values[3]
180	    };
181	    geom_point points[4] = {
182	        {values[0], values[1]},
183	        {values[0] + values[2], values[1]},
184	        {values[0] + values[2], values[1] + values[3]},
185	        {values[0], values[1] + values[3]}
186	    };
187	    for (size_t i = 0U; i < 4U; ++i) {
188	        if (!svg_shape_point_bounded(points[i])) {
189	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_NUMBER,
190	                           tokens[element].name.offset);
191	            return false;
192	        }
193	        if (!svg_shape_builder_add_edge(builder, points[i],
194	                                         points[(i + 1U) % 4U])) return false;
195	    }
196	
197	    if (values[2] == 0.0 || values[3] == 0.0) {
198	        builder->doc->images[builder->shape_index] = image;
199	        if (!svg_shape_ensure_fill_paint(builder, builder->shape_index,
200	                tokens[element].name.offset)) return false;
201	        svg_shape_paint *paint = svg_shape_paint_for_shape_mutable(
202	            builder->doc, builder->shape_index);
203	        if (paint == NULL) return false;
204	        paint->kind = SVG_SHAPE_PAINT_IMAGE;
205	        return true;
206	    }
207	    svg_xml_span href = {0};
208	    bool plain = attribute(source, tokens, context->token_count, element,
209	                           "href", NULL, &href);
210	    bool xlink = attribute(source, tokens, context->token_count, element,
211	                           "href", "xlink", &href);
212	    if (plain == xlink || (xlink && !svg_reference_xlink_is_bound(
213	            source, tokens, context->token_count)) ||
214	        !data_payload(source, href, &href)) {
215	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
216	                       plain || xlink ? href.offset : tokens[element].name.offset);
217	        return false;
218	    }
219	    if (builder->media == NULL || builder->media->decode_image == NULL ||
220	        builder->media->release_image == NULL) {
221	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
222	                       href.offset);
223	        return false;
224	    }
225	    uint8_t *encoded = NULL;
226	    size_t encoded_length = 0U;
227	    if (!decode_base64(builder, source, href, &encoded, &encoded_length))
228	        return false;
229	    svg_shape_decoded_image decoded = {0};
230	    svg_shape_media_status media_status = builder->media->decode_image(
231	        builder->media->context, (base_bytes){encoded, encoded_length},
232	        &decoded);
233	    svg_shape_free(encoded);
234	    if (media_status != SVG_SHAPE_MEDIA_OK) {
235	        svg_shape_error error = media_status == SVG_SHAPE_MEDIA_LIMIT ?
236	            SVG_SHAPE_ERROR_LIMIT : media_status == SVG_SHAPE_MEDIA_OOM ?
237	            SVG_SHAPE_ERROR_OOM : SVG_SHAPE_ERROR_UNSUPPORTED;
238	        svg_shape_fail(builder->diag, error, href.offset);
239	        return false;
240	    }
241	    size_t minimum_row;
242	    size_t required_bytes;
243	    if (decoded.rgba == NULL || decoded.width == 0U || decoded.height == 0U ||
244	        decoded.width > 16384U || decoded.height > 16384U ||
245	        (size_t)decoded.width > SIZE_MAX / 4U ||
246	        (minimum_row = (size_t)decoded.width * 4U,
247	         decoded.row_stride < minimum_row) ||
248	        (size_t)decoded.height > SIZE_MAX / decoded.row_stride ||
249	        (required_bytes = (size_t)decoded.height * decoded.row_stride,
250	         required_bytes > decoded.byte_count) ||
251	        (size_t)decoded.width > SIZE_MAX / (size_t)decoded.height) {
252	        builder->media->release_image(builder->media->context, &decoded);
253	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
254	                       href.offset);
255	        return false;
256	    }
257	    size_t pixels = (size_t)decoded.width * (size_t)decoded.height;
258	    if (pixels > SVG_SHAPE_MEDIA_MAX_IMAGE_PIXELS -
259	                 builder->decoded_image_pixels) {
260	        builder->media->release_image(builder->media->context, &decoded);
261	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT, href.offset);
262	        return false;
263	    }
264	    builder->decoded_image_pixels += pixels;
265	    image.rgba = decoded.rgba;
266	    image.byte_count = decoded.byte_count;
267	    image.row_stride = decoded.row_stride;
268	    image.pixel_width = decoded.width;
269	    image.pixel_height = decoded.height;
270	    image.owner = decoded.owner;
271	
272	    svg_shape_aspect aspect = {.align_x = 0.5, .align_y = 0.5, .set = true};
273	    svg_xml_span aspect_span;
274	    if (attribute(source, tokens, context->token_count, element,
275	                  "preserveAspectRatio", NULL, &aspect_span) &&
276	        !svg_shape_parse_preserve_aspect(source, aspect_span, &aspect)) {
277	        decoded.owner = image.owner;
278	        builder->media->release_image(builder->media->context, &decoded);
279	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
280	                       aspect_span.offset);
281	        return false;
282	    }
283	    if (!aspect.none) {
284	        double sx = image.width / (double)image.pixel_width;
285	        double sy = image.height / (double)image.pixel_height;
286	        double scale = aspect.slice ? fmax(sx, sy) : fmin(sx, sy);
287	        image.draw_width = (double)image.pixel_width * scale;
288	        image.draw_height = (double)image.pixel_height * scale;
289	        image.draw_x = image.x +
290	            (image.width - image.draw_width) * aspect.align_x;
291	        image.draw_y = image.y +
292	            (image.height - image.draw_height) * aspect.align_y;
293	    }
294	    builder->doc->images[builder->shape_index] = image;
295	    if (!svg_shape_ensure_fill_paint(builder, builder->shape_index,
296	            tokens[element].name.offset)) return false;
297	    svg_shape_paint *paint = svg_shape_paint_for_shape_mutable(
298	        builder->doc, builder->shape_index);
299	    if (paint == NULL) return false;
300	    paint->kind = SVG_SHAPE_PAINT_IMAGE;
301	    return true;
302	}
