304	bool svg_shape_builder_add_image_element(
305	    svg_shape_builder *builder, base_bytes source, svg_xml_token *tokens,
306	    size_t token_count, size_t element, const svg_css_paint *style,
307	    geom_affine transform)
308	{
309	    image_geometry_context context = {source, tokens, token_count, element};
310	    if (!svg_shape_builder_add_custom_element(
311	            builder, source, tokens, token_count, element, style, transform,
312	            image_geometry, &context)) return false;
313	    size_t shape = builder->shape_index;
314	    size_t first = builder->doc->shape_edge_start[shape];
315	    size_t count = builder->doc->shape_edge_count[shape];
316	    for (size_t i = first; i < first + count; ++i)
317	        builder->doc->colors[i * 4U + 3U] = 0U;
318	    return true;
319	}

