  7	#define TEXT_CACHE_ENTRIES 32U
  8	#define TEXT_CACHE_BYTES (256U * 1024U)
  9	#define TEXT_CACHE_COMMANDS SVG_SHAPE_MEDIA_MAX_PATH_COMMANDS
 10	
 11	typedef struct text_cache_entry {
 12	    uint8_t *text;
 13	    size_t text_length;
 14	    svg_shape_text_family *families;
 15	    size_t family_count;
 16	    double size_points;
 17	    double weight;
 18	    double letter_spacing_points;
 19	    svg_shape_text_style style;
 20	    svg_shape_text_layout layout;
 21	} text_cache_entry;
 22	
 23	struct svg_shape_text_cache {
 24	    const svg_shape_media_providers *providers;
 25	    text_cache_entry entries[TEXT_CACHE_ENTRIES];
 26	    size_t count;
 27	    size_t bytes;
 28	    size_t commands;
 29	};
 30	
 31	void svg_shape_text_layout_release(const svg_shape_media_providers *providers,
 32	                                    svg_shape_text_layout *layout)
 33	{
 34	    if (providers->release_text != NULL)
 35	        providers->release_text(providers->context, layout);
 36	    else {
 37	        free(layout->glyphs);
 38	        free(layout->commands);
 39	        *layout = (svg_shape_text_layout){0};
 40	    }
 41	}
 42	
 43	svg_shape_text_cache *svg_shape_text_cache_create(
 44	    const svg_shape_media_providers *providers)
 45	{
 46	    if (providers == NULL || providers->layout_text == NULL) return NULL;
 47	    svg_shape_text_cache *cache = svg_shape_calloc(1U, sizeof(*cache));
 48	    if (cache != NULL) cache->providers = providers;
 49	    return cache;
 50	}
 51	
 52	void svg_shape_text_cache_destroy(svg_shape_text_cache *cache)
 53	{
 54	    if (cache == NULL) return;
 55	    for (size_t i = 0U; i < cache->count; ++i) {
 56	        svg_shape_text_layout_release(cache->providers, &cache->entries[i].layout);
 57	        svg_shape_free(cache->entries[i].text);
 58	        svg_shape_free(cache->entries[i].families);
 59	    }
 60	    svg_shape_free(cache);
 61	}
 62	
 63	static bool request_matches(const text_cache_entry *entry,
 64	                            const svg_shape_text_request *request)
 65	{
 66	    if (entry->text_length != request->text.len ||
 67	        entry->family_count != request->font_family_count ||
 68	        entry->size_points != request->size_points ||
 69	        entry->weight != request->weight ||
 70	        entry->style != request->style ||
 71	        entry->letter_spacing_points != request->letter_spacing_points ||
 72	        memcmp(entry->text, request->text.ptr, request->text.len) != 0)
 73	        return false;
 74	    for (size_t i = 0U; i < entry->family_count; ++i) {
 75	        const svg_shape_text_family *a = &entry->families[i];
 76	        const svg_shape_text_family *b = &request->font_families[i];
 77	        if (a->length != b->length || memcmp(a->bytes, b->bytes, a->length) != 0)
 78	            return false;
 79	    }
 80	    return true;
 81	}
 82	
 83	bool svg_shape_text_layout_run(svg_shape_text_cache *cache,
 84	                        const svg_shape_text_request *request,
 85	                        svg_shape_text_layout *out, bool *cached,
 86	                        svg_shape_diagnostic *diagnostic,
 87	                        size_t error_offset)
 88	{
 89	    *out = (svg_shape_text_layout){0};
 90	    *cached = false;
 91	    if (cache == NULL || cache->providers->layout_text == NULL ||
 92	        cache->providers->release_text == NULL) {
 93	        svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, error_offset);
 94	        return false;
 95	    }
 96	    for (size_t i = 0U; i < cache->count; ++i) {
 97	        if (request_matches(&cache->entries[i], request)) {
 98	            *out = cache->entries[i].layout;
 99	            *cached = true;
100	            return true;
101	        }
102	    }
103	    svg_shape_media_status status = cache->providers->layout_text(
104	        cache->providers->context, request, out);
105	    if (status != SVG_SHAPE_MEDIA_OK) {
106	        svg_shape_error error = status == SVG_SHAPE_MEDIA_LIMIT ?
107	            SVG_SHAPE_ERROR_LIMIT : status == SVG_SHAPE_MEDIA_OOM ?
108	            SVG_SHAPE_ERROR_OOM : SVG_SHAPE_ERROR_UNSUPPORTED;
109	        svg_shape_fail(diagnostic, error, error_offset);
110	        return false;
111	    }
112	    if (out->glyph_count > SVG_SHAPE_MEDIA_MAX_GLYPHS ||
113	        out->command_count > SVG_SHAPE_MEDIA_MAX_PATH_COMMANDS ||
114	        (out->glyph_count != 0U && out->glyphs == NULL) ||
115	        (out->command_count != 0U && out->commands == NULL) ||
116	        !isfinite(out->advance_width)) {
117	        svg_shape_text_layout_release(cache->providers, out);
118	        svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_LIMIT, error_offset);
119	        return false;
120	    }
121	    for (size_t i = 0U; i < out->glyph_count; ++i) {
122	        const svg_shape_text_glyph *glyph = &out->glyphs[i];
123	        if (!isfinite(glyph->x) || !isfinite(glyph->y) ||
124	            !isfinite(glyph->advance) || glyph->command_start > out->command_count ||
125	            glyph->command_count > out->command_count - glyph->command_start) {
126	            svg_shape_text_layout_release(cache->providers, out);
127	            svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
128	                           error_offset);
129	            return false;
130	        }
131	    }
132	    for (size_t i = 0U; i < out->command_count; ++i) {
133	        const svg_shape_text_command *command = &out->commands[i];
134	        if ((unsigned)command->verb > (unsigned)SVG_SHAPE_TEXT_CLOSE) {
135	            svg_shape_text_layout_release(cache->providers, out);
136	            svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
137	                           error_offset);
138	            return false;
139	        }
140	        for (size_t value = 0U; value < 6U; ++value) {
141	            if (!isfinite(command->values[value])) {
142	                svg_shape_text_layout_release(cache->providers, out);
143	                svg_shape_fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
144	                               error_offset);
145	                return false;
146	            }
147	        }
148	    }
149	    if (cache->count < TEXT_CACHE_ENTRIES &&
150	        request->text.len <= TEXT_CACHE_BYTES - cache->bytes &&
151	        out->command_count <= TEXT_CACHE_COMMANDS - cache->commands &&
152	        request->font_family_count <= SVG_SHAPE_MEDIA_MAX_FAMILIES) {
153	        uint8_t *key_text = svg_shape_malloc(request->text.len == 0U ? 1U :
154	                                              request->text.len);
155	        svg_shape_text_family *families = request->font_family_count == 0U ?
156	            NULL : svg_shape_malloc(request->font_family_count * sizeof(*families));
157	        if (key_text != NULL &&
158	            (request->font_family_count == 0U || families != NULL)) {
159	            if (request->text.len != 0U)
160	                memcpy(key_text, request->text.ptr, request->text.len);
161	            if (families != NULL)
162	                memcpy(families, request->font_families,
163	                       request->font_family_count * sizeof(*families));
164	            cache->entries[cache->count] = (text_cache_entry){
165	                .text = key_text,
166	                .text_length = request->text.len,
167	                .families = families,
168	                .family_count = request->font_family_count,
169	                .size_points = request->size_points,
170	                .weight = request->weight,
171	                .letter_spacing_points = request->letter_spacing_points,
172	                .style = request->style,
173	                .layout = *out
174	            };
175	            cache->count++;
176	            cache->bytes += request->text.len;
177	            cache->commands += out->command_count;
178	            *cached = true;
179	        } else {
180	            svg_shape_free(key_text);
181	            svg_shape_free(families);
182	        }
183	    }
184	    return true;
185	}
