 26	static bool text_span_equal(base_bytes source, svg_xml_span span,
 27	                            const char *literal)
 28	{
 29	    size_t length = 0U;
 30	    while (literal[length] != '\0') length++;
 31	    return span.offset <= source.len && span.length == length &&
 32	           length <= source.len - span.offset &&
 33	           memcmp(source.ptr + span.offset, literal, length) == 0;
 34	}
