 36	static bool text_attribute(base_bytes source, const svg_xml_token *tokens,
 37	                           size_t count, size_t element, const char *local,
 38	                           const char *prefix, svg_xml_span *out)
 39	{
 40	    for (size_t i = element + 1U;
 41	         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
 42	        if (!text_span_equal(source, tokens[i].local_name, local)) continue;
 43	        if ((prefix == NULL && tokens[i].prefix.length == 0U) ||
 44	            (prefix != NULL && text_span_equal(source, tokens[i].prefix,
 45	                                                prefix))) {
 46	            *out = tokens[i].value;
 47	            return true;
 48	        }
 49	    }
 50	    return false;
 51	}
