108	static bool parse_position_list(base_bytes source, svg_xml_span span,
109	                                double reference, double **out_values,
110	                                size_t *out_count, size_t *error_offset)
111	{
112	    *out_values = NULL;
113	    *out_count = 0U;
114	    if (span.length == 0U || span.offset > source.len ||
115	        span.length > source.len - span.offset) {
116	        *error_offset = span.offset;
117	        return false;
118	    }
119	    size_t capacity = span.length < SVG_SHAPE_MEDIA_MAX_GLYPHS ?
120	                      span.length : SVG_SHAPE_MEDIA_MAX_GLYPHS;
121	    if (capacity == 0U || capacity > SIZE_MAX / sizeof(double)) {
122	        *error_offset = span.offset;
123	        return false;
124	    }
125	    double *values = svg_shape_malloc(capacity * sizeof(*values));
126	    if (values == NULL) return false;
127	    size_t i = 0U, count = 0U;
128	    bool need_value = true;
129	    while (i < span.length) {
130	        while (i < span.length && (source.ptr[span.offset + i] == ' ' ||
131	               source.ptr[span.offset + i] == '\t' ||
132	               source.ptr[span.offset + i] == '\r' ||
133	               source.ptr[span.offset + i] == '\n')) i++;
134	        if (i == span.length) break;
135	        if (source.ptr[span.offset + i] == ',') {
136	            if (need_value) { *error_offset = span.offset + i; goto invalid; }
137	            need_value = true;
138	            i++;
139	            continue;
140	        }
141	        size_t start = i;
142	        while (i < span.length && source.ptr[span.offset + i] != ',' &&
143	               source.ptr[span.offset + i] != ' ' &&
144	               source.ptr[span.offset + i] != '\t' &&
145	               source.ptr[span.offset + i] != '\r' &&
146	               source.ptr[span.offset + i] != '\n') i++;
147	        if (count == capacity || start == i ||
148	            !svg_shape_read_length(source,
149	                (svg_xml_span){span.offset + start, i - start}, reference,
150	                &values[count])) {
151	            *error_offset = span.offset + start;
152	            goto invalid;
153	        }
154	        count++;
155	        need_value = false;
156	    }
157	    if (count == 0U || need_value) {
158	        *error_offset = span.offset + span.length;
159	        goto invalid;
160	    }
161	    *out_values = values;
162	    *out_count = count;
163	    return true;
164	invalid:
165	    svg_shape_free(values);
166	    return false;
167	}
