225	static bool parse_size(base_bytes source, const svg_css_paint *style,
226	                       double reference, double *out, size_t *error_offset)
227	{
228	    svg_xml_span span;
229	    *out = 16.0;
230	    if (!svg_css_paint_value(style, SVG_CSS_FONT_SIZE, &span)) return true;
231	    if (!svg_shape_read_length(source, span, reference, out) || *out <= 0.0) {
232	        *error_offset = span.offset;
233	        return false;
234	    }
235	    return true;
236	}
