238	static bool parse_weight(base_bytes source, const svg_css_paint *style,
239	                         double *out, size_t *error_offset)
240	{
241	    svg_xml_span span;
242	    *out = 400.0;
243	    if (!svg_css_paint_value(style, SVG_CSS_FONT_WEIGHT, &span)) return true;
244	    if (svg_css_keyword_equals(source, span, "normal")) return true;
245	    if (svg_css_keyword_equals(source, span, "bold")) { *out = 700.0; return true; }
246	    if (!svg_shape_read_number(source, span, out) || *out < 100.0 ||
247	        *out > 900.0 || fmod(*out, 100.0) != 0.0) {
248	        *error_offset = span.offset;
249	        return false;
250	    }
251	    return true;
252	}
