269	static bool parse_text_style(base_bytes source, const svg_css_paint *style,
270	                             double viewport_width,
271	                             double viewport_height,
272	                             svg_shape_text_request *request,
273	                             svg_shape_text_family families[
274	                                 SVG_SHAPE_MEDIA_MAX_FAMILIES],
275	                             size_t *family_count, double *word_spacing,
276	                             bool *anchor_middle, bool *anchor_end,
277	                             size_t *error_offset)
278	{
279	    double font_size = 16.0;
280	    if (!parse_size(source, style, viewport_height, &font_size, error_offset) ||
281	        !parse_weight(source, style, &request->weight, error_offset) ||
282	        !parse_families(source, style, families, family_count, error_offset) ||
283	        !parse_spacing(source, style, SVG_CSS_LETTER_SPACING,
284	                       viewport_width, &request->letter_spacing_points,
285	                       error_offset) ||
286	        !parse_spacing(source, style, SVG_CSS_WORD_SPACING,
287	                       viewport_width, word_spacing, error_offset)) return false;
288	    request->font_families = families;
289	    request->font_family_count = *family_count;
290	    request->size_points = font_size * 0.75;
291	    request->letter_spacing_points *= 0.75;
292	    request->style = SVG_SHAPE_TEXT_NORMAL;
293	    svg_xml_span span;
294	    if (svg_css_paint_value(style, SVG_CSS_FONT_STYLE, &span)) {
295	        if (svg_css_keyword_equals(source, span, "italic"))
296	            request->style = SVG_SHAPE_TEXT_ITALIC;
297	        else if (svg_css_keyword_equals(source, span, "oblique"))
298	            request->style = SVG_SHAPE_TEXT_OBLIQUE;
299	        else if (!svg_css_keyword_equals(source, span, "normal")) {
300	            *error_offset = span.offset;
301	            return false;
302	        }
303	    }
304	    *anchor_middle = false;
305	    *anchor_end = false;
306	    if (svg_css_paint_value(style, SVG_CSS_TEXT_ANCHOR, &span)) {
307	        if (svg_css_keyword_equals(source, span, "middle"))
308	            *anchor_middle = true;
309	        else if (svg_css_keyword_equals(source, span, "end"))
310	            *anchor_end = true;
311	        else if (!svg_css_keyword_equals(source, span, "start")) {
312	            *error_offset = span.offset;
313	            return false;
314	        }
315	    }
316	    return true;
317	}
