409	bool svg_shape_text_render_element(
410	    svg_shape_builder *builder, base_bytes source, svg_xml_token *tokens,
411	    size_t token_count, size_t element, size_t end,
412	    const svg_css_paint *style, geom_affine transform,
413	    size_t source_offset, size_t source_length,
414	    svg_shape_text_state *state, bool parent_preserve_space,
415	    bool *out_preserve_space)
416	{
417	    if (builder == NULL || style == NULL || state == NULL ||
418	        out_preserve_space == NULL || element >= token_count || end >= token_count) {
419	        svg_shape_fail(builder == NULL ? NULL : builder->diag,
420	                       SVG_SHAPE_ERROR_INVALID_ARGUMENT, 0U);
421	        return false;
422	    }
423	    size_t error_offset = tokens[element].name.offset;
424	    bool preserve = parent_preserve_space;
425	    if (!parse_xml_space(source, tokens, token_count, element,
426	                         parent_preserve_space, &preserve, &error_offset)) {
427	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
428	                       error_offset);
429	        return false;
430	    }
431	    svg_shape_text_family families[SVG_SHAPE_MEDIA_MAX_FAMILIES] = {{0}};
432	    size_t family_count = 0U;
433	    svg_shape_text_request request = {0};
434	    double word_spacing = 0.0;
435	    bool anchor_middle = false, anchor_end = false;
436	    if (!parse_text_style(source, style, builder->viewport_width,
437	                          builder->viewport_height, &request, families,
438	                          &family_count, &word_spacing, &anchor_middle,
439	                          &anchor_end, &error_offset)) {
440	        svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
441	                       error_offset);
442	        return false;
443	    }
444	    for (size_t i = element + 1U; i < end; ++i) {
445	        const svg_xml_token *token = &tokens[i];
446	        if ((token->kind != SVG_XML_TOKEN_TEXT &&
447	             token->kind != SVG_XML_TOKEN_CDATA) ||
448	            token->depth != tokens[element].depth + 1U) continue;
449	        if (token->value.length > SVG_SHAPE_MEDIA_MAX_TEXT_BYTES ||
450	            token->value.length > SVG_SHAPE_MEDIA_MAX_DOCUMENT_TEXT_BYTES -
451	                                  builder->text_bytes) {
452	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT,
453	                           token->value.offset);
454	            return false;
455	        }
456	        builder->text_bytes += token->value.length;
457	        uint8_t *normalized = NULL;
458	        size_t normalized_length = 0U;
459	        size_t entity_error = token->value.offset;
460	        if (!normalize_text(source, token->value, preserve, state,
461	                            &normalized, &normalized_length, &entity_error)) {
462	            svg_shape_fail(builder->diag, entity_error == token->value.offset ?
463	                SVG_SHAPE_ERROR_OOM : SVG_SHAPE_ERROR_UNSUPPORTED,
464	                entity_error);
465	            return false;
466	        }
467	        if (normalized_length == 0U) {
468	            svg_shape_free(normalized);
469	            continue;
470	        }
471	        request.text = (base_bytes){normalized, normalized_length};
472	        svg_shape_text_layout layout = {0};
473	        bool cached = false;
474	        if (!svg_shape_text_layout_run(builder->text_cache, &request,
475	                                       &layout, &cached,
476	                         builder->diag, token->value.offset)) {
477	            svg_shape_free(normalized);
478	            return false;
479	        }
480	        if (layout.glyph_count > SVG_SHAPE_MEDIA_MAX_DOCUMENT_GLYPHS -
481	                                 builder->text_glyphs ||
482	            layout.command_count > SVG_SHAPE_MEDIA_MAX_DOCUMENT_PATH_COMMANDS -
483	                                   builder->text_commands) {
484	            if (!cached) svg_shape_text_layout_release(builder->media, &layout);
485	            svg_shape_free(normalized);
486	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_LIMIT,
487	                           token->value.offset);
488	            return false;
489	        }
490	        builder->text_glyphs += layout.glyph_count;
491	        builder->text_commands += layout.command_count;
492	        size_t outline_commands = 0U;
493	        for (size_t g = 0U; g < layout.glyph_count; ++g)
494	            outline_commands += layout.glyphs[g].command_count;
495	        double x_reference = builder->viewport_width;
496	        double y_reference = builder->viewport_height;
497	        double *x_values = NULL, *y_values = NULL;
498	        double *dx_values = NULL, *dy_values = NULL;
499	        size_t x_count = 0U, y_count = 0U, dx_count = 0U, dy_count = 0U;
500	        const char *names[] = {"x", "y", "dx", "dy"};
501	        double **arrays[] = {&x_values, &y_values, &dx_values, &dy_values};
502	        size_t *counts[] = {&x_count, &y_count, &dx_count, &dy_count};
503	        double references[] = {x_reference, y_reference,
504	                               x_reference, y_reference};
505	        bool lists_ok = true;
506	        for (size_t list = 0U; list < 4U; ++list) {
507	            svg_xml_span position;
508	            if (text_attribute(source, tokens, token_count, element,
509	                               names[list], NULL, &position) &&
510	                !parse_position_list(source, position, references[list],
511	                    arrays[list], counts[list], &error_offset)) {
512	                lists_ok = false;
513	                break;
514	            }
515	        }
516	        if (!lists_ok) {
517	            svg_shape_free(x_values); svg_shape_free(y_values);
518	            svg_shape_free(dx_values); svg_shape_free(dy_values);
519	            if (!cached) svg_shape_text_layout_release(builder->media, &layout);
520	            svg_shape_free(normalized);
521	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_NUMBER,
522	                           error_offset);
523	            return false;
524	        }
525	        double start_x = state->cursor_x;
526	        double start_y = state->cursor_y;
527	        if (x_count != 0U) start_x = x_values[0];
528	        if (y_count != 0U) start_y = y_values[0];
529	        if (dx_count != 0U) start_x += dx_values[0];
530	        if (dy_count != 0U) start_y += dy_values[0];
531	        const double unit_scale = 96.0 / 72.0;
532	        double advance_units = layout.advance_width * unit_scale;
533	        double anchor = anchor_middle ? -advance_units * 0.5 :
534	                        anchor_end ? -advance_units : 0.0;
535	        size_t codepoints = 0U, spaces = 0U;
536	        for (size_t p = 0U; p < normalized_length; ++p) {
537	            if ((normalized[p] & 0xC0U) != 0x80U) {
538	                codepoints++;
539	                if (normalized[p] == ' ') spaces++;
540	            }
541	        }
542	        if (word_spacing != 0.0 && codepoints != layout.glyph_count) {
543	            svg_shape_free(x_values); svg_shape_free(y_values);
544	            svg_shape_free(dx_values); svg_shape_free(dy_values);
545	            if (!cached) svg_shape_text_layout_release(builder->media, &layout);
546	            svg_shape_free(normalized);
547	            svg_shape_fail(builder->diag, SVG_SHAPE_ERROR_UNSUPPORTED,
548	                           token->value.offset);
549	            return false;
550	        }
551	        if (outline_commands != 0U) {
552	            outline_context context = {
553	                .layout = &layout,
554	                .x_values = x_values, .x_count = x_count,
555	                .y_values = y_values, .y_count = y_count,
556	                .dx_values = dx_values, .dx_count = dx_count,
557	                .dy_values = dy_values, .dy_count = dy_count,
558	                .start_x = start_x, .start_y = start_y,
559	                .anchor_offset = anchor, .unit_scale = unit_scale,
560	                .word_spacing = word_spacing,
561	                .text = normalized, .text_length = normalized_length
562	            };
563	            size_t first_shape = builder->doc->shape_count;
564	            if (!svg_shape_builder_add_custom_element(
565	                    builder, source, tokens, token_count, element, style,
566	                    transform, text_geometry, &context) ||
567	                !svg_shape_source_assign(builder->doc, first_shape,
568	                    builder->doc->shape_count, source_offset, source_length)) {
569	                svg_shape_free(x_values); svg_shape_free(y_values);
570	                svg_shape_free(dx_values); svg_shape_free(dy_values);
571	                if (!cached) svg_shape_text_layout_release(builder->media, &layout);
572	                svg_shape_free(normalized);
573	                return false;
574	            }
575	        }
576	        state->cursor_x = start_x + advance_units +
577	                          (double)spaces * word_spacing;
578	        state->cursor_y = start_y;
579	        state->has_position = true;
580	        svg_shape_free(x_values); svg_shape_free(y_values);
581	        svg_shape_free(dx_values); svg_shape_free(dy_values);
582	        if (!cached) svg_shape_text_layout_release(builder->media, &layout);
583	        svg_shape_free(normalized);
584	    }
585	    *out_preserve_space = preserve;
586	    return true;
587	}

