 10	/// Convert provider glyph outlines into the owned flattened path used by the
 11	/// shared scene API. This follows the original 96/72 scale, baseline sign,
 12	/// x/y overrides, accumulated dx/dy, anchor, and word-spacing rules.
 13	pub fn text_geometry(
 14	    layout: &TextLayout,
 15	    text: &[u8],
 16	    x: &[f64],
 17	    y: &[f64],
 18	    dx: &[f64],
 19	    dy: &[f64],
 20	    start: [f64; 2],
 21	    anchor_offset: f64,
 22	    word_spacing: f64,
 23	    transform: vexel_geometry::Affine,
 24	    control: &mut dyn WorkControl,
 25	) -> Result<Vec<vexel_geometry::Edge>> {
 26	    Ok(text_path_geometry(
 27	        layout, text, x, y, dx, dy, start, anchor_offset, word_spacing, transform, control,
 28	    )?
 29	    .edges)
 30	}
