189	/// Decode direct text/CDATA children of a text or tspan element. Each authored
190	/// run creates one owned scene shape, with source identity fixed at append time.
191	/// A failed request or commit restores the scene suffix, document command
192	/// budget, external text state and newly admitted cache entries. Earlier scene
193	/// handles and cache layouts retain their identity.
194	pub fn render_text_request(
195	    request: vexel_scene::TextDecodeRequest<'_, '_>,
196	    builder: &mut vexel_scene::SceneBuilder,
197	    draft: &vexel_scene::DraftToken,
198	    control: &mut dyn WorkControl,
199	) -> Result<bool> {
200	    request.validate_source_map(builder, control)?;
201	    let state_before = *request.state;
202	    let cache_before = (request.cache.entries.len(), request.cache.text_bytes, request.cache.commands);
203	    let result = super::request::atomic_request(builder, draft, control, |builder, control| {
204	        render_text_element(
205	            request.element, request.end, request.scene, request.source_map,
206	            request.style, request.transform, &mut *request.state,
207	            request.preserve_space, request.provider, &mut *request.cache,
208	            builder, draft, control,
209	        )
210	    });
211	    if result.is_err() {
212	        *request.state = state_before;
213	        request.cache.entries.truncate(cache_before.0);
214	        request.cache.text_bytes = cache_before.1;
215	        request.cache.commands = cache_before.2;
216	    }
217	    result
218	}
