429	        kind: match stop {
430	            vexel_base::Stop::Canceled => ErrorKind::Canceled,
431	            vexel_base::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
432	            vexel_base::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
433	        },
434	        offset: 0,
435	    }
