392	/// Decode and append an image through the accepted typed request contract.
393	/// The host annotation is validated before parsing, provider calls, or mutation,
394	/// then stored verbatim on the appended shape while `transform` maps geometry.
395	pub fn decode_image_request(
396	    request: vexel_scene::ImageDecodeRequest<'_, '_>,
397	    builder: &mut vexel_scene::SceneBuilder,
398	    draft: &vexel_scene::DraftToken,
399	    control: &mut dyn WorkControl,
400	) -> Result<vexel_scene::ShapeId> {
401	    request.validate_source_map(builder, control)?;
402	    super::request::atomic_request(builder, draft, control, |builder, control| {
403	        let viewport = builder.scene(request.scene)?.viewport;
404	        let plan = image_element(
405	            request.element,
406	            [viewport.view_width, viewport.view_height],
407	            request.provider,
408	            control,
409	        )?;
410	        append_image_plan_mapped(
411	            plan, request.source_map, request.scene, request.transform,
412	            builder, draft, control,
413	        )
414	    })
415	}
