 4	/// Keep request cleanup independent of cancellation. A failed commit still
 5	/// owns its request token, so scene validation failures follow the same path.
 6	pub(crate) fn atomic_request<T>(
 7	    builder: &mut SceneBuilder,
 8	    draft: &DraftToken,
 9	    control: &mut dyn WorkControl,
10	    operation: impl FnOnce(&mut SceneBuilder, &mut dyn WorkControl) -> Result<T>,
11	) -> Result<T> {
12	    let token = builder.begin_request(draft, control)?;
13	    let result = operation(builder, control).and_then(|value| {
14	        builder.commit_request(draft, token, control)?;
15	        Ok(value)
16	    });
17	    if result.is_err() {
18	        builder.rollback_request(draft, token)?;
19	    }
20	    result
21	}

