137	/// Parse a comma-separated CSS family list, removing paired quotes as the C implementation does.
138	pub fn parse_families(source: &[u8], style: &CssPaint<'_>) -> Result<Vec<Vec<u8>>> {
139	    parse_families_with_spans(source, style).map(|(families, _)| families)
140	}
141	
142	fn parse_families_with_spans(
143	    source: &[u8],
144	    style: &CssPaint<'_>,
145	) -> Result<(Vec<Vec<u8>>, Vec<Span>)> {
146	    let Some(value) = style.value(Property::FontFamily) else {
147	        return Ok((Vec::new(), Vec::new()));
148	    };
149	    let span = value.span;
150	    if span.slice(source) != Some(value.bytes) {
151	        return Err(fail(ErrorKind::Unsupported, span.offset));
152	    }
153	    let bytes = value.bytes;
154	    let mut i = 0;
155	    let mut families = Vec::new();
156	    let mut spans = Vec::new();
157	    families
158	        .try_reserve_exact(MAX_FAMILIES.min(bytes.len()))
159	        .map_err(|_| fail(ErrorKind::OutOfMemory, span.offset))?;
160	    spans
161	        .try_reserve_exact(MAX_FAMILIES.min(bytes.len()))
162	        .map_err(|_| fail(ErrorKind::OutOfMemory, span.offset))?;
163	    while i < bytes.len() {
164	        while i < bytes.len() && whitespace(bytes[i]) {
165	            i += 1;
166	        }
167	        if i == bytes.len() {
168	            break;
169	        }
170	        if families.len() == MAX_FAMILIES {
171	            return Err(fail(
172	                ErrorKind::Unsupported,
173	                span.offset + i,
174	            ));
175	        }
176	        let start;
177	        let end;
178	        if matches!(bytes[i], b'\'' | b'"') {
179	            let quote = bytes[i];
180	            i += 1;
181	            start = i;
182	            while i < bytes.len() && bytes[i] != quote {
183	                i += 1;
184	            }
185	            if i == bytes.len() {
186	                return Err(fail(ErrorKind::Unsupported, span.offset + start - 1));
187	            }
188	            end = i;
189	            i += 1;
190	        } else {
191	            start = i;
192	            while i < bytes.len() && bytes[i] != b',' {
193	                i += 1;
194	            }
195	            let mut trimmed = i;
196	            while trimmed > start && whitespace(bytes[trimmed - 1]) {
197	                trimmed -= 1;
198	            }
199	            end = trimmed;
200	        }
201	        if end == start {
202	            return Err(fail(ErrorKind::Unsupported, span.offset + start));
203	        }
204	        let mut family = Vec::new();
205	        family
206	            .try_reserve_exact(end - start)
207	            .map_err(|_| fail(ErrorKind::OutOfMemory, span.offset + start))?;
208	        family.extend_from_slice(&bytes[start..end]);
209	        families.push(family);
210	        let absolute_start = span
211	            .offset
212	            .checked_add(start)
213	            .ok_or_else(|| fail(ErrorKind::Limit(LimitKind::Arithmetic), span.offset))?;
214	        let absolute_end = span
215	            .offset
216	            .checked_add(end)
217	            .ok_or_else(|| fail(ErrorKind::Limit(LimitKind::Arithmetic), span.offset))?;
218	        spans.push(Span {
219	            start: absolute_start,
220	            end: absolute_end,
221	        });
222	        while i < bytes.len() && bytes[i] != b',' {
223	            if !whitespace(bytes[i]) {
224	                return Err(fail(ErrorKind::Unsupported, span.offset + i));
225	            }
226	            i += 1;
227	        }
228	        if i < bytes.len() {
229	            i += 1;
230	        }
231	    }
232	    if families.is_empty() {
233	        Err(fail(ErrorKind::Unsupported, span.offset))
234	    } else {
235	        Ok((families, spans))
236	    }
237	}
