 48	/// Borrowed cache hit or an owned provider result when admission prevents caching.
 49	pub enum LayoutResult<'a> {
 50	    Cached(&'a TextLayout),
 51	    Owned(TextLayout),
 52	}
 53	impl LayoutResult<'_> {
 54	    pub fn layout(&self) -> &TextLayout {
 55	        match self {
 56	            Self::Cached(v) => v,
 57	            Self::Owned(v) => v,
 58	        }
 59	    }
 60	    pub fn is_cached(&self) -> bool {
 61	        matches!(self, Self::Cached(_))
 62	    }
 63	}
 64	
 65	impl TextCache {
 66	    pub fn new() -> Self {
 67	        Self::default()
 68	    }
 69	    pub fn len(&self) -> usize {
 70	        self.entries.len()
 71	    }
 72	    pub fn is_empty(&self) -> bool {
 73	        self.entries.is_empty()
 74	    }
 75	    pub fn stored_text_bytes(&self) -> usize {
 76	        self.text_bytes
 77	    }
 78	    pub fn stored_commands(&self) -> usize {
 79	        self.commands
 80	    }
 81	
 82	    /// Run explicit provider layout and validate the owned output before caching.
 83	    pub fn layout<'a>(
 84	        &'a mut self,
 85	        request: TextRequest<'_>,
 86	        provider: &mut dyn MediaProvider,
 87	        control: &mut dyn WorkControl,
 88	        offset: usize,
 89	    ) -> Result<LayoutResult<'a>> {
 90	        request.validate(control)?;
 91	        if let Some(i) = self
 92	            .entries
 93	            .iter()
 94	            .position(|entry| entry.key.matches(request))
 95	        {
 96	            return Ok(LayoutResult::Cached(&self.entries[i].layout));
 97	        }
 98	        let layout = provider
 99	            .layout_text(request, control)
100	            .map_err(|e| provider_error(e, offset))?;
101	        validate_layout(&layout, offset, control)?;
102	        let text_ok = request.text.len() <= TEXT_CACHE_BYTES.saturating_sub(self.text_bytes);
103	        let command_ok = layout.commands.len() <= MAX_PATH_COMMANDS.saturating_sub(self.commands);
104	        if self.entries.len() < TEXT_CACHE_ENTRIES && text_ok && command_ok {
105	            let key = try_key(request);
106	            if let Some(key) = key {
107	                if self.entries.try_reserve(1).is_ok() {
108	                    self.text_bytes += request.text.len();
109	                    self.commands += layout.commands.len();
110	                    self.entries.push(Entry { key, layout });
111	                    let last = self.entries.len() - 1;
112	                    return Ok(LayoutResult::Cached(&self.entries[last].layout));
113	                }
114	            }
115	        }
116	        Ok(LayoutResult::Owned(layout))
117	    }
118	}
