311	/// Work-accounting helper for consumers that traverse outline verbs.
312	pub fn charge_outline(control: &mut dyn WorkControl, units: usize) -> Result<()> {
313	    control
314	        .charge(
315	            WorkKind::Media,
316	            u64::try_from(units).map_err(|_| Diagnostic {
317	                kind: ErrorKind::Limit(LimitKind::Arithmetic),
318	                offset: 0,
319	            })?,
320	        )
321	        .map_err(|stop| Diagnostic {
322	            kind: match stop {
323	                vexel_base::Stop::Canceled => ErrorKind::Canceled,
324	                vexel_base::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
325	                vexel_base::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
326	            },
327	            offset: 0,
328	        })
329	}

