439	fn append_image_plan_mapped(
440	    plan: ImagePlan,
441	    source_map: vexel_scene::SourceMap,
442	    scene: vexel_scene::SceneId,
443	    transform: vexel_geometry::Affine,
444	    builder: &mut vexel_scene::SceneBuilder,
445	    draft: &vexel_scene::DraftToken,
446	    control: &mut dyn WorkControl,
447	) -> Result<vexel_scene::ShapeId> {
448	    let source = source_map.element;
449	    if source.slice(builder.source_owner().as_slice()).is_none() {
450	        return Err(fail(ErrorKind::InvalidArgument, source.start));
451	    }
452	    let geom = plan.geometry;
453	    let mut image_index = None;
454	    if let Some(pixels) = plan.pixels {
455	        let index = builder.append_image(
456	            scene,
457	            vexel_scene::Image {
458	                pixels,
459	                x: geom.x,
460	                y: geom.y,
461	                width: geom.width,
462	                height: geom.height,
463	                draw_x: geom.draw_x,
464	                draw_y: geom.draw_y,
465	                draw_width: geom.draw_width,
466	                draw_height: geom.draw_height,
467	            },
468	            control,
469	        )?;
470	        image_index = Some(index);
471	    }
472	    let points = [
473	        vexel_geometry::Point {
474	            x: geom.x,
475	            y: geom.y,
476	        },
477	        vexel_geometry::Point {
478	            x: geom.x + geom.width,
479	            y: geom.y,
480	        },
481	        vexel_geometry::Point {
482	            x: geom.x + geom.width,
483	            y: geom.y + geom.height,
484	        },
485	        vexel_geometry::Point {
486	            x: geom.x,
487	            y: geom.y + geom.height,
488	        },
489	    ];
490	    let mut edges = Vec::new();
491	    edges
492	        .try_reserve_exact(4)
493	        .map_err(|_| fail(ErrorKind::OutOfMemory, plan.source.offset))?;
494	    for i in 0..4 {
495	        let a = vexel_geometry::affine_map_point(transform, points[i])
496	            .ok_or_else(|| fail(ErrorKind::Number, source.start))?;
497	        let b = vexel_geometry::affine_map_point(transform, points[(i + 1) % 4])
498	            .ok_or_else(|| fail(ErrorKind::Number, source.start))?;
499	        edges.push(vexel_geometry::Edge { a, b });
500	    }
501	    let mut subpaths = Vec::new();
502	    subpaths
503	        .try_reserve_exact(1)
504	        .map_err(|_| fail(ErrorKind::OutOfMemory, plan.source.offset))?;
505	    subpaths.push(vexel_svg_path::PathSubpath {
506	        first_edge: 0,
507	        edge_count: 4,
508	        closed: true,
509	    });
510	    let path = vexel_svg_path::PathDocument {
511	        edges,
512	        subpaths,
513	        segments: Vec::new(),
514	        numbers: Vec::new(),
515	    };
516	    let mut colors = Vec::new();
517	    colors
518	        .try_reserve_exact(4)
519	        .map_err(|_| fail(ErrorKind::OutOfMemory, plan.source.offset))?;
520	    colors.resize(4, [0; 4]);
521	    let mut shape = vexel_scene::Shape::new(source_map);
522	    shape.image = image_index;
523	    let id = builder.append_shape(
524	        scene,
525	        vexel_scene::ShapeInput {
526	            shape,
527	            path,
528	            edge_colors: colors,
529	        },
530	        control,
531	    )?;
532	    let published = *builder
533	        .scene(scene)?
534	        .shape(id)
535	        .ok_or_else(|| fail(ErrorKind::InvalidArgument, source.start))?;
536	    builder.finalize_shape(draft, id, published, control)?;
537	    Ok(id)
538	}
539	fn xlink_is_bound(source: &[u8], tokens: &[XmlToken]) -> bool {
540	    for (i, token) in tokens.iter().enumerate() {
541	        if token.kind != TokenKind::StartElement || token.depth != 0 {
542	            continue;
543	        }
544	        for attr in tokens
545	            .get(i + 1..)
546	            .unwrap_or_default()
547	            .iter()
548	            .take_while(|t| t.kind == TokenKind::Attribute)
549	        {
550	            if attr.name.slice(source) == Some(b"xmlns:xlink")
551	                && attr.value.slice(source) == Some(b"http://www.w3.org/1999/xlink")
552	            {
553	                return true;
554	            }
555	        }
556	        return false;
557	    }
558	    false
559	}
560	fn media_error(error: MediaError, offset: usize) -> Diagnostic {
561	    let kind = match error {
562	        MediaError::InvalidArgument
563	        | MediaError::Unsupported
564	        | MediaError::Invalid
565	        | MediaError::InvalidUtf8
566	        | MediaError::Animated
567	        | MediaError::Corrupt => ErrorKind::Unsupported,
568	        MediaError::Limit => ErrorKind::Limit(LimitKind::Images),
569	        MediaError::OutOfMemory => ErrorKind::OutOfMemory,
570	    };
571	    fail(kind, offset)
572	}

