 32	/// Preserve one closed subpath per provider contour, including contours closed
 33	/// implicitly by a subsequent Move or the end of a glyph.
 34	pub fn text_path_geometry(
 35	    layout: &TextLayout,
 36	    text: &[u8],
 37	    x: &[f64],
 38	    y: &[f64],
 39	    dx: &[f64],
 40	    dy: &[f64],
 41	    start: [f64; 2],
 42	    anchor_offset: f64,
 43	    word_spacing: f64,
 44	    transform: vexel_geometry::Affine,
 45	    control: &mut dyn WorkControl,
 46	) -> Result<vexel_svg_path::PathDocument> {
 47	    let mut edges = Vec::new();
 48	    let mut subpaths = Vec::new();
 49	    let mut codepoint = 0;
 50	    let mut extra_x = 0.;
 51	    let mut extra_y = 0.;
 52	    let mut word_offset = 0.;
 53	    let scale = 96. / 72.;
 54	    for (glyph_index, glyph) in layout.glyphs.iter().enumerate() {
 55	        control.checkpoint().map_err(stopped)?;
 56	        if glyph_index < dx.len() {
 57	            extra_x += dx[glyph_index];
 58	        }
 59	        if glyph_index < dy.len() {
 60	            extra_y += dy[glyph_index];
 61	        }
 62	        let x_override = glyph_index < x.len();
 63	        let y_override = glyph_index < y.len();
 64	        if x_override {
 65	            extra_x = 0.;
 66	        }
 67	        if y_override {
 68	            extra_y = 0.;
 69	        }
 70	        let gx = (if x_override {
 71	            x[glyph_index]
 72	        } else {
 73	            start[0] + glyph.x * scale
 74	        }) + extra_x
 75	            + anchor_offset
 76	            + word_offset;
 77	        let gy = (if y_override {
 78	            y[glyph_index]
 79	        } else {
 80	            start[1] - glyph.y * scale
 81	        }) + extra_y;
 82	        while codepoint < text.len() && text[codepoint] & 0xc0 == 0x80 {
 83	            codepoint += 1;
 84	        }
 85	        if codepoint < text.len() && text[codepoint] == b' ' {
 86	            word_offset += word_spacing;
 87	        }
 88	        while codepoint < text.len() && text[codepoint] & 0xc0 != 0x80 {
 89	            codepoint += 1;
 90	        }
 91	        let range_end = glyph
 92	            .commands
 93	            .first
 94	            .checked_add(glyph.commands.count)
 95	            .filter(|&end| end <= layout.commands.len())
 96	            .ok_or_else(|| fail(ErrorKind::Unsupported, 0))?;
 97	        let mut current = vexel_geometry::Point { x: 0., y: 0. };
 98	        let mut first = current;
 99	        let mut open = false;
100	        let mut contour_first = edges.len();
101	        for command in &layout.commands[glyph.commands.first..range_end] {
102	            control
103	                .charge(vexel_base::WorkKind::Media, 1)
104	                .map_err(stopped)?;
105	            let point = |i: usize| vexel_geometry::Point {
106	                x: gx + command.values[i] * scale,
107	                y: gy - command.values[i + 1] * scale,
108	            };
109	            match command.verb {
110	                vexel_scene::TextVerb::Move => {
111	                    if open {
112	                        close_contour(current, first, contour_first, transform, &mut edges, &mut subpaths, control)?;
113	                    }
114	                    contour_first = edges.len();
115	                    current = point(0);
116	                    first = current;
117	                    open = true;
118	                }
119	                vexel_scene::TextVerb::Line => {
120	                    let next = point(0);
121	                    if !open {
122	                        contour_first = edges.len();
123	                        first = current;
124	                        open = true;
125	                    }
126	                    append_text_edge(current, next, transform, &mut edges, control)?;
127	                    current = next;
128	                }
129	                vexel_scene::TextVerb::Cubic => {
130	                    let c1 = point(0);
131	                    let c2 = point(2);
132	                    let next = point(4);
133	                    if !open {
134	                        contour_first = edges.len();
135	                        first = current;
136	                        open = true;
137	                    }
138	                    vexel_svg_path::flatten_cubic_controlled(
139	                        [current, c1, c2, next],
140	                        transform,
141	                        vexel_svg_path::ParseOptions::default(),
142	                        0,
143	                        &mut edges,
144	                        control,
145	                    )
146	                    .map_err(path_control_error)?;
147	                    current = next;
148	                }
149	                vexel_scene::TextVerb::Close => {
150	                    if open {
151	                        close_contour(current, first, contour_first, transform, &mut edges, &mut subpaths, control)?;
152	                    }
153	                    current = first;
154	                    open = false;
155	                }
156	            }
157	        }
158	        if open {
159	            close_contour(current, first, contour_first, transform, &mut edges, &mut subpaths, control)?;
160	        }
161	    }
162	    Ok(vexel_svg_path::PathDocument {
163	        edges,
164	        subpaths,
165	        segments: Vec::new(),
166	        numbers: Vec::new(),
167	    })
168	}
