220	fn render_text_element(
221	    view: vexel_scene::ElementView<'_>,
222	    end: usize,
223	    scene: vexel_scene::SceneId,
224	    source_map: vexel_scene::SourceMap,
225	    style: &CssPaint<'_>,
226	    transform: vexel_geometry::Affine,
227	    state: &mut TextState,
228	    parent_preserve_space: bool,
229	    provider: &mut dyn vexel_scene::MediaProvider,
230	    cache: &mut vexel_scene::TextCache,
231	    builder: &mut vexel_scene::SceneBuilder,
232	    draft: &vexel_scene::DraftToken,
233	    control: &mut dyn WorkControl,
234	) -> Result<bool> {
235	    view.validate(control)?;
236	    let source = view.source();
237	    let tokens = view.tokens();
238	    let element = view.element.0;
239	    if source_map.element.slice(source).is_none() {
240	        return Err(fail(ErrorKind::InvalidArgument, source_map.element.start));
241	    }
242	    let preserve = parse_xml_space(source, tokens, element, end, parent_preserve_space)?;
243	    let viewport = builder.scene(scene)?.viewport;
244	    let viewport_size = [viewport.view_width, viewport.view_height];
245	    let values = parse_text_style(source, style, viewport_size)?;
246	    let mut family_refs: Vec<&[u8]> = Vec::new();
247	    family_refs
248	        .try_reserve_exact(values.families.len())
249	        .map_err(|_| fail(ErrorKind::OutOfMemory, tokens[element].name.offset))?;
250	    family_refs.extend(values.families.iter().map(Vec::as_slice));
251	    for token in tokens
252	        .get(element + 1..end)
253	        .ok_or_else(|| fail(ErrorKind::InvalidArgument, 0))?
254	    {
255	        control
256	            .charge(vexel_base::WorkKind::TokenVisit, 1)
257	            .map_err(stopped)?;
258	        if token.depth > tokens[element].depth
259	            && matches!(
260	                token.kind,
261	                vexel_xml::TokenKind::StartElement | vexel_xml::TokenKind::EmptyElement
262	            )
263	            && token.local_name.slice(source) == Some(b"textPath")
264	        {
265	            return Err(fail(ErrorKind::Unsupported, token.name.offset));
266	        }
267	    }
268	    for token in tokens
269	        .get(element + 1..end)
270	        .ok_or_else(|| fail(ErrorKind::InvalidArgument, 0))?
271	    {
272	        control
273	            .charge(vexel_base::WorkKind::TokenVisit, 1)
274	            .map_err(stopped)?;
275	        if !matches!(
276	            token.kind,
277	            vexel_xml::TokenKind::Text | vexel_xml::TokenKind::Cdata
278	        ) || token.depth != tokens[element].depth + 1
279	        {
280	            continue;
281	        }
282	        if token.value.length > MAX_TEXT_BYTES
283	            || state.text_bytes > 64 * 1024 * 1024
284	            || token.value.length > (64 * 1024 * 1024usize).saturating_sub(state.text_bytes)
285	        {
286	            return Err(fail(
287	                ErrorKind::Limit(LimitKind::TextBytes),
288	                token.value.offset,
289	            ));
290	        }
291	        state.text_bytes = state
292	            .text_bytes
293	            .checked_add(token.value.length)
294	            .ok_or_else(|| fail(ErrorKind::Limit(LimitKind::Arithmetic), token.value.offset))?;
295	        let normalized = normalize_text(source, token.value, preserve, state)?;
296	        if normalized.is_empty() {
297	            continue;
298	        }
299	        let request = TextRequest {
300	            text: &normalized,
301	            font_families: &family_refs,
302	            size_points: values.size_points,
303	            weight: values.weight,
304	            style: values.style,
305	            letter_spacing_points: values.letter_spacing_points,
306	        };
307	        let output = super::text_cache::layout_shared(
308	            cache,
309	            request,
310	            &values.family_spans,
311	            provider,
312	            control,
313	            token.value.offset,
314	        )?;
315	        let layout = output.layout();
316	        if state.glyph_count > 1_048_576usize
317	            || layout.glyphs.len() > 1_048_576usize - state.glyph_count
318	        {
319	            return Err(fail(
320	                ErrorKind::Limit(LimitKind::Glyphs),
321	                token.value.offset,
322	            ));
323	        }
324	        builder.admit_text_commands(draft, layout.commands.len(), token.value.offset, control)?;
325	        state.glyph_count = state
326	            .glyph_count
327	            .checked_add(layout.glyphs.len())
328	            .ok_or_else(|| fail(ErrorKind::Limit(LimitKind::Arithmetic), token.value.offset))?;
329	        let x = parse_positions_if_present(source, tokens, element, end, b"x", viewport_size[0])?;
330	        let y = parse_positions_if_present(source, tokens, element, end, b"y", viewport_size[1])?;
331	        let dx = parse_positions_if_present(source, tokens, element, end, b"dx", viewport_size[0])?;
332	        let dy = parse_positions_if_present(source, tokens, element, end, b"dy", viewport_size[1])?;
333	        let start_x =
334	            x.first().copied().unwrap_or(state.cursor_x) + dx.first().copied().unwrap_or(0.);
335	        let start_y =
336	            y.first().copied().unwrap_or(state.cursor_y) + dy.first().copied().unwrap_or(0.);
337	        let codepoints = normalized.iter().filter(|b| **b & 0xc0 != 0x80).count();
338	        let spaces = normalized.iter().filter(|b| **b == b' ').count();
339	        if values.word_spacing != 0. && codepoints != layout.glyphs.len() {
340	            return Err(fail(ErrorKind::Unsupported, token.value.offset));
341	        }
342	        let anchor_offset = match values.anchor {
343	            vexel_scene::TextAnchor::Start => 0.,
344	            vexel_scene::TextAnchor::Middle => -layout.advance_width * (96. / 72.) * 0.5,
345	            vexel_scene::TextAnchor::End => -layout.advance_width * (96. / 72.),
346	        };
347	        if layout.glyphs.iter().any(|g| g.commands.count != 0) {
348	            let path = text_path_geometry(
349	                layout,
350	                &normalized,
351	                &x,
352	                &y,
353	                &dx,
354	                &dy,
355	                [start_x, start_y],
356	                anchor_offset,
357	                values.word_spacing,
358	                transform,
359	                control,
360	            )?;
361	            if !path.edges.is_empty() {
362	                let mut colors = Vec::new();
363	                colors
364	                    .try_reserve_exact(path.edges.len())
365	                    .map_err(|_| fail(ErrorKind::OutOfMemory, token.value.offset))?;
366	                colors.resize(path.edges.len(), [0; 4]);
367	                let mut shape = vexel_scene::Shape::new(source_map);
368	                shape.filled = true;
369	                let id = builder.append_shape(
370	                    scene,
371	                    vexel_scene::ShapeInput {
372	                        shape,
373	                        path,
374	                        edge_colors: colors,
375	                    },
376	                    control,
377	                )?;
378	                let published = *builder
379	                    .scene(scene)?
380	                    .shape(id)
381	                    .ok_or_else(|| fail(ErrorKind::InvalidArgument, source_map.element.start))?;
382	                builder.finalize_shape(draft, id, published, control)?;
383	            }
384	        }
385	        state.cursor_x =
386	            start_x + layout.advance_width * (96. / 72.) + spaces as f64 * values.word_spacing;
387	        state.cursor_y = start_y;
388	        state.has_position = true;
389	    }
390	    Ok(preserve)
391	}
