393	fn parse_positions_if_present(
394	    source: &[u8],
395	    tokens: &[XmlToken],
396	    element: usize,
397	    end: usize,
398	    name: &[u8],
399	    reference: f64,
400	) -> Result<Vec<f64>> {
401	    match text_attribute(source, tokens, element, end, name, None) {
402	        Some(span) => parse_position_list(source, span, reference),
403	        None => Ok(Vec::new()),
