407	fn append_text_edge(
408	    from: vexel_geometry::Point,
409	    to: vexel_geometry::Point,
410	    transform: vexel_geometry::Affine,
411	    edges: &mut Vec<vexel_geometry::Edge>,
412	    control: &mut dyn WorkControl,
413	) -> Result<()> {
414	    vexel_svg_path::append_edge(
415	        from,
416	        to,
417	        transform,
418	        vexel_svg_path::MAX_PATH_EDGES,
419	        0,
420	        edges,
421	    )
422	    .map_err(path_error)?;
423	    control
424	        .charge(vexel_base::WorkKind::Edge, 1)
425	        .map_err(stopped)
