427	fn stopped(stop: vexel_base::Stop) -> Diagnostic {
428	    Diagnostic {
429	        kind: match stop {
430	            vexel_base::Stop::Canceled => ErrorKind::Canceled,
431	            vexel_base::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
432	            vexel_base::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
433	        },
434	        offset: 0,
435	    }
436	}
437	fn path_error(error: vexel_svg_path::Diagnostic) -> Diagnostic {
438	    Diagnostic {
439	        kind: match error.kind {
440	            vexel_svg_path::DiagnosticKind::Limit => ErrorKind::Limit(LimitKind::PathCommands),
441	            vexel_svg_path::DiagnosticKind::OutOfMemory => ErrorKind::OutOfMemory,
442	            vexel_svg_path::DiagnosticKind::Number
443	            | vexel_svg_path::DiagnosticKind::InvalidTransform => ErrorKind::Number,
444	            _ => ErrorKind::Unsupported,
445	        },
446	        offset: error.offset,
447	    }
448	}
449	fn path_control_error(
450	    error: vexel_base::ControlledError<vexel_svg_path::Diagnostic>,
451	) -> Diagnostic {
452	    match error {
453	        vexel_base::ControlledError::Original(error) => path_error(error),
454	        vexel_base::ControlledError::Canceled => stopped(vexel_base::Stop::Canceled),
455	        vexel_base::ControlledError::Limit => stopped(vexel_base::Stop::Limit),
456	        vexel_base::ControlledError::Overflow => stopped(vexel_base::Stop::Overflow),
457	        vexel_base::ControlledError::OutOfMemory => Diagnostic {
458	            kind: ErrorKind::OutOfMemory,
459	            offset: 0,
460	        },
461	    }
462	}

 53	static bool normalize_text(base_bytes source, svg_xml_span raw,
 54	                           bool preserve, svg_shape_text_state *state,
 55	                           uint8_t **out_bytes, size_t *out_length,
 56	                           size_t *error_offset)
 57	{
 58	    *out_bytes = NULL;
 59	    *out_length = 0U;
 60	    if (raw.offset > source.len || raw.length > source.len - raw.offset)
 61	        return false;
 62	    uint8_t *decoded = svg_shape_malloc(raw.length == 0U ? 1U : raw.length);
 63	    if (decoded == NULL) return false;
 64	    size_t decoded_length = 0U;
 65	    size_t decode_error = 0U;
 66	    if (!svg_xml_decode_attribute_value(source, raw, decoded, raw.length,
 67	                                        &decoded_length, &decode_error)) {
 68	        *error_offset = raw.offset + decode_error;
 69	        svg_shape_free(decoded);
 70	        return false;
 71	    }
 72	    if (preserve) {
 73	        if (decoded_length != 0U) state->has_position = true;
 74	        *out_bytes = decoded;
 75	        *out_length = decoded_length;
 76	        return true;
 77	    }
 78	    uint8_t *collapsed = svg_shape_malloc(decoded_length == 0U ? 1U :
 79	                                           decoded_length);
 80	    if (collapsed == NULL) {
 81	        svg_shape_free(decoded);
 82	        return false;
 83	    }
 84	    size_t output = 0U;
 85	    size_t i = 0U;
 86	    while (i < decoded_length) {
 87	        uint8_t byte = decoded[i];
 88	        bool whitespace = byte == ' ' || byte == '\t' || byte == '\r' ||
 89	                          byte == '\n';
 90	        if (whitespace) {
 91	            if (state->has_position || output != 0U) state->pending_space = true;
 92	            i++;
 93	            continue;
 94	        }
 95	        if (state->pending_space && (state->has_position || output != 0U))
 96	            collapsed[output++] = ' ';
 97	        state->pending_space = false;
 98	        collapsed[output++] = byte;
 99	        state->has_position = true;
100	        i++;
101	    }
102	    svg_shape_free(decoded);
103	    *out_bytes = collapsed;
104	    *out_length = output;
105	    return true;
106	}
