254	static bool parse_spacing(base_bytes source, const svg_css_paint *style,
255	                          svg_css_property property, double reference,
256	                          double *out, size_t *error_offset)
257	{
258	    svg_xml_span span;
259	    *out = 0.0;
260	    if (!svg_css_paint_value(style, property, &span) ||
261	        svg_css_keyword_equals(source, span, "normal")) return true;
262	    if (!svg_shape_read_length(source, span, reference, out)) {
263	        *error_offset = span.offset;
264	        return false;
265	    }
266	    return true;
267	}
