319	static bool text_geometry(svg_shape_builder *builder, void *opaque)
320	{
321	    outline_context *context = opaque;
322	    const svg_shape_text_layout *layout = context->layout;
323	    size_t codepoint = 0U;
324	    double extra_x = 0.0, extra_y = 0.0, word_offset = 0.0;
325	    for (size_t glyph_index = 0U; glyph_index < layout->glyph_count;
326	         ++glyph_index) {
327	        const svg_shape_text_glyph *glyph = &layout->glyphs[glyph_index];
328	        bool x_override = glyph_index < context->x_count;
329	        bool y_override = glyph_index < context->y_count;
330	        if (glyph_index < context->dx_count) extra_x += context->dx_values[glyph_index];
331	        if (glyph_index < context->dy_count) extra_y += context->dy_values[glyph_index];
332	        if (x_override) extra_x = 0.0;
333	        if (y_override) extra_y = 0.0;
334	        double gx = (x_override ? context->x_values[glyph_index] :
335	                     context->start_x + glyph->x * context->unit_scale) + extra_x +
336	                    context->anchor_offset + word_offset;
337	        double gy = (y_override ? context->y_values[glyph_index] :
338	                     context->start_y - glyph->y * context->unit_scale) + extra_y;
339	        while (codepoint < context->text_length &&
340	               (context->text[codepoint] & 0xC0U) == 0x80U) codepoint++;
341	        if (codepoint < context->text_length && context->text[codepoint] == ' ')
342	            word_offset += context->word_spacing;
343	        while (codepoint < context->text_length &&
344	               (context->text[codepoint] & 0xC0U) != 0x80U) codepoint++;
345	        geom_point current = {0.0, 0.0}, first = {0.0, 0.0};
346	        bool open = false;
347	        size_t end = glyph->command_start + glyph->command_count;
348	        for (size_t index = glyph->command_start; index < end; ++index) {
349	            const svg_shape_text_command *command = &layout->commands[index];
350	            if (command->verb == SVG_SHAPE_TEXT_MOVE) {
351	                if (open && !svg_shape_builder_add_edge(builder, current, first))
352	                    return false;
353	                current = (geom_point){gx + command->values[0] * context->unit_scale,
354	                                       gy - command->values[1] * context->unit_scale};
355	                first = current;
356	                open = true;
357	            } else if (command->verb == SVG_SHAPE_TEXT_LINE) {
358	                geom_point next = {gx + command->values[0] * context->unit_scale,
359	                                   gy - command->values[1] * context->unit_scale};
360	                if (!open) { first = current; open = true; }
361	                if (!svg_shape_builder_add_edge(builder, current, next))
362	                    return false;
363	                current = next;
364	            } else if (command->verb == SVG_SHAPE_TEXT_CUBIC) {
365	                geom_point c1 = {gx + command->values[0] * context->unit_scale,
366	                                 gy - command->values[1] * context->unit_scale};
367	                geom_point c2 = {gx + command->values[2] * context->unit_scale,
368	                                 gy - command->values[3] * context->unit_scale};
369	                geom_point next = {gx + command->values[4] * context->unit_scale,
370	                                   gy - command->values[5] * context->unit_scale};
371	                if (!open) { first = current; open = true; }
372	                if (!svg_shape_builder_add_curve(builder, current, c1, c2,
373	                                                 next)) return false;
374	                current = next;
375	            } else {
376	                if (open && !svg_shape_builder_add_edge(builder, current, first))
377	                    return false;
378	                current = first;
379	                open = false;
380	            }
381	        }
382	        if (open && !svg_shape_builder_add_edge(builder, current, first))
383	            return false;
384	    }
385	    return true;
386	}
