211	impl WorkControl for StopOnTextFinalize {
212	    fn charge(&mut self, kind: WorkKind, units: u64) -> std::result::Result<(), Stop> {
213	        if kind == WorkKind::Edge { self.edges += units as usize; }
214	        Ok(())
215	    }
