217	        // Four geometry edges, four path-validation edges, four publish edges.
218	        // The publish checkpoint succeeds; finalization then stops.
219	        if self.edges == 12 {
220	            self.final_checkpoints += 1;
221	            if self.final_checkpoints == 2 { return Err(Stop::Canceled); }
222	        }
223	        Ok(())
224	    }
