 11	}
 12	impl Interrupt {
 13	    fn event(&mut self) -> std::result::Result<(), Stop> {
 14	        self.events += 1;
 15	        if let Some(left) = &mut self.remaining {
 16	            if *left == 0 { return Err(self.stop); }
 17	            *left -= 1;
 18	        }
 19	        Ok(())
 20	    }
 21	}
 22	impl WorkControl for Interrupt {
