 34	fn interrupt_probe(text: bool, at: Option<usize>, stop: Stop) -> usize {
 35	    let mut fixture = Fixture::new(SOURCE, Limits::default());
 36	    let scene = fixture.builder.root_id();
 37	    let index = fixture.index(if text { b"text" } else { b"image" });
 38	    let map = fixture.map(index);
 39	    let element = view(&fixture.lex, index);
 40	    let draft = fixture.builder.begin_draft(scene).unwrap();
 41	    let input = fixture.prefix_input();
 42	    let prefix = fixture.builder.append_shape(scene, input, &mut Run).unwrap();
 43	    let prefix_value = *fixture.builder.scene(scene).unwrap().shape(prefix).unwrap();
 44	    let prefix_edges = fixture.builder.scene(scene).unwrap().edges.to_vec();
 45	    let mut ledger = ChargeLedger::new(fixture.lex.source_owner(), 1 << 20, 8).unwrap();
 46	    let ledger_before = ledger.stats().live_bytes;
 47	    let mut state = TextState { cursor_x: 7., cursor_y: 9., text_bytes: 13,
 48	        glyph_count: 2, has_position: true, pending_space: true };
 49	    let state_before = state_value(state);
 50	    let mut provider = Provider::default();
 51	    let mut cache = TextCache::default();
 52	    assert!(layout_shared_cache(&mut cache, prefix_request(), &[], &mut provider,
 53	        &mut Run, 0).unwrap().is_cached());
 54	    let key_pointer = cache.entries[0].text.as_ptr();
 55	    let commands_pointer = cache.entries[0].layout.commands.as_ptr();
 56	    let mut control = Interrupt { remaining: at, events: 0, stop };
 57	    let result = if text {
 58	        render_text_request(TextDecodeRequest { element, source_map: map, end: element.end,
 59	            style: &CssPaint::initial(), transform: vexel_geometry::affine_identity(),
 60	            state: &mut state, preserve_space: false, provider: &mut provider,
 61	            cache: &mut cache, scene, ledger: &mut ledger },
 62	            &mut fixture.builder, &draft, &mut control).map(|_| ())
 63	    } else {
 64	        decode_image_request(ImageDecodeRequest { element, source_map: map,
 65	            style: &CssPaint::initial(), transform: vexel_geometry::affine_identity(),
 66	            provider: &mut provider, scene, ledger: &mut ledger },
 67	            &mut fixture.builder, &draft, &mut control).map(|_| ())
 68	    };
 69	    if let Some(at) = at {
 70	        let expected = match stop {
 71	            Stop::Canceled => ErrorKind::Canceled,
 72	            Stop::Limit => ErrorKind::Limit(LimitKind::Work),
 73	            Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
 74	        };
 75	        assert_eq!(result.unwrap_err().kind, expected, "text={text}, interruption={at}");
 76	        assert_eq!(control.events, at + 1, "rollback must not poll stopped control");
 77	        let restored = fixture.builder.scene(scene).unwrap();
 78	        assert_eq!(restored.shapes.len(), 1);
 79	        assert!(restored.images.is_empty());
 80	        assert_eq!(restored.edges, prefix_edges);
 81	        assert_eq!(restored.path_subpaths.len(), 1);
 82	        assert_eq!(restored.shape(prefix).unwrap().source, prefix_value.source);
 83	        assert_eq!(state_value(state), state_before);
 84	        assert_eq!((cache.entries.len(), cache.text_bytes, cache.commands), (1, 6, 5));
 85	        assert_eq!(cache.entries[0].text.as_ptr(), key_pointer);
 86	        assert_eq!(cache.entries[0].layout.commands.as_ptr(), commands_pointer);
 87	        assert_eq!(fixture.builder.document_text_commands(), 0);
 88	        let calls = provider.seen.len();
 89	        assert!(layout_shared_cache(&mut cache, prefix_request(), &[], &mut provider,
 90	            &mut Run, 0).unwrap().is_cached());
 91	        assert_eq!(provider.seen.len(), calls);
 92	    } else {
 93	        result.unwrap();
 94	        assert_eq!(fixture.builder.scene(scene).unwrap().shapes.len(), if text { 3 } else { 2 });
 95	        assert_eq!(fixture.builder.scene(scene).unwrap().images.len(), usize::from(!text));
 96	        assert_eq!(fixture.builder.document_text_commands(), if text { 10 } else { 0 });
 97	    }
 98	    assert_eq!(ledger.stats().live_bytes, ledger_before);
 99	    fixture.builder.finalize_shape(&draft, prefix, prefix_value, &mut Run).unwrap();
100	    // A second real append and outer commit prove usable authorization, rather
101	    // than relying on an outer rollback to erase the failed request.
102	    let input = fixture.prefix_input();
103	    fixture.builder.append_shape(scene, input, &mut Run).unwrap();
104	    fixture.builder.commit_draft(&draft, &mut Run).unwrap();
105	    assert!(fixture.builder.scene(scene).unwrap().shape(prefix).is_some());
106	    control.events
107	}
