127	struct FailingProvider { inner: Provider, calls: usize, failure: Option<MediaError> }
128	impl MediaProvider for FailingProvider {
129	    fn layout_text(&mut self, request: TextRequest<'_>, control: &mut dyn WorkControl)
130	        -> std::result::Result<TextLayout, MediaError>
131	    {
132	        self.calls += 1;
133	        if self.calls == 2 {
134	            if let Some(error) = self.failure { return Err(error); }
135	            let mut malformed = self.inner.layout_text(request, control)?;
136	            malformed.glyphs[0].commands = TableRange { first: usize::MAX, count: 2 };
137	            return Ok(malformed);
138	        }
139	        self.inner.layout_text(request, control)
140	    }
141	    fn decode_image(&mut self, _: &[u8], _: &mut dyn WorkControl)
142	        -> std::result::Result<ImagePixels, MediaError>
143	    { self.calls += 1; Err(self.failure.unwrap_or(MediaError::Corrupt)) }
144	}
145	fn errors() -> [MediaError; 8] {
146	    [MediaError::OutOfMemory, MediaError::Limit, MediaError::Unsupported, MediaError::Invalid,
147	        MediaError::InvalidArgument, MediaError::InvalidUtf8, MediaError::Animated, MediaError::Corrupt]
148	}
149	fn expected(error: MediaError, text: bool) -> ErrorKind {
150	    match error {
151	        MediaError::OutOfMemory => ErrorKind::OutOfMemory,
152	        MediaError::Limit => ErrorKind::Limit(if text { LimitKind::TextCommands } else { LimitKind::Images }),
153	        _ => ErrorKind::Unsupported,
154	    }
155	}
