    43	macro_rules! room {
    44	    ($self:ident,$index:expr,$field:ident,$extra:expr,$cap:expr,$pending:expr) => {{
    45	        let pending = $pending;
    46	        let current = add($self.stats.live_bytes, pending)?;
    47	        let available = $self
    48	            .limits
    49	            .reserved_bytes
    50	            .checked_sub(current)
    51	            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
    52	        // Check all counters before the mutating reserve can transfer old values.
    53	        let history_room = usize::MAX - $self.stats.total_allocated_bytes;
    54	        let available = available.min(history_room);
    55	        if $self.stats.allocation_count == usize::MAX {
    56	            return Err(arithmetic());
    57	        }
    58	        let (new, old) = reserve(&mut $self.scenes[$index].$field, $extra, $cap, available)?;
    59	        if new != 0 {
    60	            $self.stats.peak_live_bytes = $self.stats.peak_live_bytes.max(add(current, new)?);
    61	            $self.stats.total_allocated_bytes = add($self.stats.total_allocated_bytes, new)?;
    62	            $self.stats.allocation_count += 1;
    63	            $self.stats.live_bytes = add($self.stats.live_bytes - old, new)?;
    64	        }
    65	    }};
    66	}
